window.kbPageData["views/entry/k-fb501bd210c1cbd0"] = {"key":"entry/k-fb501bd210c1cbd0","state":{"route":"entry/k-fb501bd210c1cbd0"},"node":{"id":"k-fb501bd210c1cbd0","mode":"k","title":"增强党性①是全面从严治党的根本性任务","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["公报解读正文"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["二十届五中全会"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"党的二十届五中全会","slug":"6a94c2ad76dd"}],"directorySummary":"（一）增强党性①是全面从严治党的根本性任务\n必须推动全体党员、干部坚持党的性质和宗旨，增强党的意识、党员意识、先锋队意识，\n把加强党性修养作为终身课题，在坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事\n求是、纯正道德品质、保持清正廉洁②等方面下功夫，做到忠诚干净担当，始终保持共产党\n人政治本色。…","sources":[{"id":"7f8ebc0151f0130b","label":"增强党性①是全面从严治党的根本性任务","topic":"二十届五中全会","category":"时政","text":"（一）增强党性①是全面从严治党的根本性任务\n必须推动全体党员、干部坚持党的性质和宗旨，增强党的意识、党员意识、先锋队意识，\n把加强党性修养作为终身课题，在坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事\n求是、纯正道德品质、保持清正廉洁②等方面下功夫，做到忠诚干净担当，始终保持共产党\n人政治本色。要强化对党忠诚教育，坚持用党的创新理论凝心铸魂，用党的优良传统和中华\n优秀传统文化涵养党性，在实践中锤炼党性，加强党性鉴别。","source":{"doc":"41195a191a57c1c36332","first":12,"last":13,"page":12,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-fb501bd210c1cbd0":[]}};
